function cargoIcon(x,y,count){return count?`<g class="cargo-marker" transform="translate(${x+10} ${y-10})" aria-label="${count} dropped equipment"><circle r="8" fill="#ffe18c" stroke="#302d23" stroke-width="1.5"/><text class="cargo-count" y="4">${count}</text></g>`:''}
function flareIcon(){return ''}
function signalIcon(x,y){return `<g class="signal-icon" transform="translate(${x} ${y})" aria-label="Distress transmission"><circle r="15" fill="#062923" stroke="#72e7d3" stroke-width="1.5"/><circle cx="0" cy="7" r="2.8" fill="#9dffee"/><path class="signal-wave wave-1" d="M-5 3Q0-4 5 3"/><path class="signal-wave wave-2" d="M-9 2Q0-10 9 2"/><path class="signal-wave wave-3" d="M-13 1Q0-16 13 1"/></g>`}
function board(){const S=55,X=360,Y=315;let pieces=[],out=['<svg viewBox="20 8 680 614" role="img" aria-label="Hexagonal alien planet board"><defs><radialGradient id="fogGrad"><stop offset="0" stop-color="#226c4b"/><stop offset=".55" stop-color="#184b3d"/><stop offset="1" stop-color="#0a2b25"/></radialGradient></defs>'];for(let c of CELLS){let t=tile(c.k),x=X+Math.sqrt(3)*S*(c.q+c.r/2),y=Y+1.5*S*c.r,id=c.k.replace(',','_');let pts=Array.from({length:6},(_,i)=>`${x+S*Math.cos((60*i-30)*Math.PI/180)},${y+S*Math.sin((60*i-30)*Math.PI/180)}`).join(' '),valid=!!ui.mode&&targetValid(c.k);
 out.push(`<g data-hex="${c.k}" style="--player-color:${COLOURS[s.turn]}"><defs><clipPath id="clip_${id}"><polygon points="${pts}"/></clipPath></defs><polygon points="${pts}" fill="transparent"/>`);
 if(!t.known||ui.revealing[c.k])out.push(`<g class="dark-layer ${ui.revealing[c.k]?'illuminating':''}" clip-path="url(#clip_${id})" pointer-events="none"><polygon points="${pts}" fill="#020907"/><path d="M${x-38} ${y+16}l19-8 18 5 23-15 M${x-18} ${y-30}l13 9 21-5" fill="none" stroke="#183127" stroke-width="1" opacity=".45"/></g>`);
 out.push(`<polygon class="hex ${ui.selected===c.k?'sel':''} ${s.alien===c.k&&t.known?'danger':''} ${valid?'target':''} ${ui.mode&&ui.targetHex===c.k?'chosen':''}  ${!ui.mode&&dist(me().pos,c.k)===1&&s.moves>0&&!me().captive?'reach':''}" points="${pts}" fill="none" pointer-events="all"/>`);
 if(t.known){if(t.site?.status==='hidden'&&t.site.kind!=='cargo')pieces.push(signalIcon(x-29,y-25));if(t.site?.status==='found'||t.groundScientists)pieces.push(`<text class="marker scientist-marker" x="${x-28}" y="${y-22}" fill="#c5ffe1">✚</text>`);if(t.loose.length)pieces.push(cargoIcon(x+27,y-26,t.loose.length))}
 else if((t.site?.decoy&&t.site.status==='hidden')||t.intel)pieces.push(signalIcon(x-29,y-25));
 s.players.forEach((p,i)=>{if(s.phase==='departing'&&s.departure.people.includes(i))return;if(p.pos!==c.k||!t.known)return;let n=s.players.slice(0,i).filter(a=>a.pos===c.k).length,tx=x-21+(n%3)*21,ty=y+25+Math.floor(n/3)*20,initial=esc((p.name.trim().charAt(0)||'?').toUpperCase());pieces.push(`<g class="crew-token ${p.captive?'captive':''} ${s.phase==='play'&&i===s.turn?'active-turn':''}" transform="translate(${tx} ${ty})" style="--piece-color:${COLOURS[i]}" aria-label="${esc(p.name)}${p.scientist?' escorting a scientist':''}"><circle class="helmet-rim" r="13"/><circle r="10" fill="#10221f"/><ellipse cy="-2" rx="8" ry="5" fill="#285052"/><path d="M-3-11L0-15 3-11" fill="var(--piece-color)"/><text class="crew-initial" y="5">${initial}</text>${p.scientist?'<circle cx="10" cy="-10" r="6" fill="#f6fff7"/><text class="scientist-tag" x="10" y="-7">✚</text>':''}</g>`)});
 if(t.known&&t.terrain==='void')out.push(`<polygon points="${pts}" fill="#000" opacity=".65" pointer-events="none"/>`);
 if(s.flares.some(f=>f.hex===c.k))pieces.push(flareIcon(x+8,y+8));
out.push('</g>')}for(const gun of s.sentries||[])pieces.push(sentryIcon(gun));pieces.push(alienIcon());pieces.push(swarmMarkup());out.push('</svg>');return out.join('')+'<canvas class="dropship-canvas" width="680" height="614" aria-hidden="true"></canvas><svg class="piece-layer" viewBox="20 8 680 614" aria-label="Board markers" role="img">'+pieces.join('')+'</svg>'}
function hexCentre(k){let c=MAP[k];return [360+Math.sqrt(3)*55*(c.q+c.r/2),315+82.5*c.r]}
function alienIcon(){let motion=ui.alienMotion,echo=ui.motionEcho?.until>Date.now()&&ui.motionEcho.hex===s.alien;if(!echo&&!motion&&!tile(s.alien).known)return '';let from=motion?.from||s.alien,to=motion?.to||s.alien;if(!echo&&!tile(from).known&&!tile(to).known)return '';let a=hexCentre(from),b=hexCentre(to),progress=motion?Math.min(1,(Date.now()-motion.started)/motion.duration):1,x=a[0]+(b[0]-a[0])*progress,y=a[1]+(b[1]-a[1])*progress,seconds=motion?Math.max(.001,(motion.duration-(Date.now()-motion.started))/1000):0;let opacity=echo?1:tile(from).known?tile(to).known?1:Math.max(0,1-progress*5):Math.max(0,(progress-.8)*5);return `<g class="alien-travel" transform="translate(${x} ${y})" opacity="${opacity}" pointer-events="none" aria-label="Alien creature">${motion?`<animateTransform attributeName="transform" type="translate" from="${x} ${y}" to="${b[0]} ${b[1]}" dur="${seconds}s" fill="freeze"/><animate attributeName="opacity" values="${opacity};${tile(to).known?1:0}" dur="${Math.min(seconds,.2)}s" begin="${!tile(from).known?Math.max(0,seconds-.2):0}s" fill="freeze"/>`:''}<g class="alien-presence" transform="translate(27 -25)"><circle class="alien-halo" r="18"/><path class="alien-core" d="M0-12C8-12 13-7 12 1 12 8 6 13-2 12-10 11-14 5-12-2-11-9-6-12 0-12Z"/><circle class="alien-heart" r="5"/></g></g>`}
