 if(a==='reveal'||a==='startTurn'){if(s.phase!=='handoff')return;let first=!me().briefed;s.phase='play';ui.private=false;ui.privateKind='';ui.flipping='in';ui.terminalHold=first&&me().role==='companyRepresentative';const game=s,turn=s.turn;setTimeout(()=>{if(s!==game||s.turn!==turn)return;ui.flipping='';ui.terminalHold=false;if(first&&me().role==='companyRepresentative'){ui.private=true;ui.privateKind='briefing'}else{me().briefed=true}finish()},1000);finish();return}
 if(ui.flipping||ui.rolling)return;
 if(a==='closePrivate'){if(ui.privateKind==='briefing')me().briefed=true;save();ui.private=false;ui.privateKind='';ui.privateResult='';render();return}
 if(ui.privateKind==='briefing')return;
 if(a==='privateActions'){ui.private=true;ui.privateKind='actions';render();return}
 if(a==='eventYes'||a==='eventNo'){chooseEvent(a==='eventYes');return}if(a==='cancelLaunch')return;if(a==='depart'){finishLaunch();return}if(a==='end'){flipEndTurn();return}
 if(s.pendingEvent||s.phase!=='play')return;
 if(a==='confirmTarget'){if(!ui.targetHex)return;if(ui.mode==='itemTarget')return useItem();if(ui.mode==='decoy')return plant(ui.targetHex);if(ui.mode==='redirect')return redirect(ui.targetHex)}
 if(a==='cancelTarget'){cancelTarget();return}
